from pathlib import Path
import os,time,json,subprocess,sys
s=Path('/home/claude/.scratch/eka-benchmark');r=Path('/home/claude/code/EKA2L1');state=s/'mode3-literal-timing-state.json'
def phase(name,**kw):
 state.write_text(json.dumps(dict(phase=name,utc=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),**kw),indent=2)+'\n');print(name,kw,flush=True)
def foreign():
 rows={}
 for p in Path('/proc').iterdir():
  if not p.name.isdecimal():continue
  try:
   args=(p/'cmdline').read_bytes().split(b'\0');args=[x.decode(errors='replace')for x in args if x]
   fields=(p/'stat').read_text().rsplit(')',1)[1].split();parent=int(fields[1])
  except (OSError,ValueError,IndexError):continue
  rows[int(p.name)]=(parent,args)
 own={os.getpid()}
 while True:
  add={pid for pid,(parent,_)in rows.items()if parent in own}
  if add<=own:break
  own|=add
 found=[]
 for pid,(parent,args)in rows.items():
  if pid in own or not args:continue
  exe=Path(args[0]).name
  active=exe.startswith('node')and any(x.endswith('/profile.ts')or x=='profile.ts'or('service-overlap-'in x and x.endswith('.ts'))or Path(x).name in ('benchmark.ts','live.ts','softkeys.ts','route.ts')or x.endswith('/test_aot_wasm.js')or x.endswith('/eka_cpu_fault_wasm.js')for x in args[1:])
  active|=exe.startswith('eka_cpu_fault_')
  active|=exe in ('cmake','ninja','make','cc1','cc1plus','clang','clang++','clang-23','wasm-opt','wasm-ld','ld.lld','emcc','em++')
  if active:found.append(dict(pid=pid,parent=parent,args=args))
 return found
def telemetry(scene,batch,start):
 read_start=time.perf_counter()
 sample=dict(seconds=time.time()-start,utc=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),frequency_khz={},temperatures_millidegrees={})
 for path in sorted(Path('/sys/devices/system/cpu/cpufreq').glob('policy*/scaling_cur_freq')):
  try:sample['frequency_khz'][path.parent.name]=int(path.read_text())
  except (OSError,ValueError):pass
 for path in sorted(Path('/sys/class/thermal').glob('thermal_zone*/temp')):
  try:sample['temperatures_millidegrees'][path.parent.name+':'+(path.parent/'type').read_text().strip()]=int(path.read_text())
  except (OSError,ValueError):pass
 try:sample['loadavg']=Path('/proc/loadavg').read_text().strip()
 except OSError:pass
 try:sample['completed_rows']=len(json.loads((s/f'mode3-literal-timing-{scene}-{batch}/measurements.json').read_text()))
 except (OSError,ValueError):sample['completed_rows']=0
 sample['observer_duration_seconds']=time.perf_counter()-read_start
 return sample
try:
 assert json.loads((s/'mode3-literal-acceptance-complete.json').read_text())['accepted'] is True
 assert (r/'src/tests/benchmark/MODE3_REMAINING_EVIDENCE.json').exists()
 for scene,batch in [('long','a'),('standard','a'),('long','b'),('standard','b')]:
  phase('waiting_for_quiet',scene=scene,batch=batch)
  quiet=0
  while quiet<15:
   jobs=foreign();quiet=0 if jobs else quiet+1;time.sleep(2)
  phase('timing',scene=scene,batch=batch)
  observed={};start=time.time();host_samples=[]
  with(s/f'mode3-literal-timing-{scene}-{batch}-driver.log').open('w')as log:
   child=subprocess.Popen(['bash','-lc',f'source {s}/write-protection-gpu.env\npython3 {s}/run_mode3_literal_timing.py {scene} {batch}'],cwd=r,stdout=log,stderr=subprocess.STDOUT)
   while child.poll()is None:
    host_samples.append(telemetry(scene,batch,start))
    for job in foreign():
     key=str(job['pid']);observed.setdefault(key,dict(**job,first_seconds=time.time()-start))['last_seconds']=time.time()-start
    time.sleep(2)
  evidence=dict(telemetry=host_samples,telemetry_note='Passive sysfs readings every two seconds across startup, warmup and measurement; not a cause attribution or exclusion criterion.',scene=scene,batch=batch,returncode=child.returncode,observer_interval_seconds=2,foreign_jobs=list(observed.values()),note='Host process observer excludes its own descendants; it does not measure all possible host contention or normalize timings.')
  (s/f'mode3-literal-timing-{scene}-{batch}-host.json').write_text(json.dumps(evidence,indent=2)+'\n')
  if child.returncode:raise RuntimeError('Timing harness failed')
  if observed:raise RuntimeError('Observed concurrent profiling; completed batch retained, queue held')
 phase('all_timing_complete')
except Exception as e:phase('failure',error=str(e));raise
